DELL_COMPARE_TABLES = {
  'dell-latitude-5420-vs-5430-which-to-buy': ('Dell Latitude 5420 vs 5430 at a glance', '''<div class="cmp-wrap"><table class="cmp-table cmp-table--vs"><thead><tr><th>&nbsp;</th><th>Latitude 5420</th><th>Latitude 5430</th></tr></thead><tbody><tr><th>Best for</th><td>Office, email, browsing &amp; Microsoft 365</td><td>Heavier multitasking &amp; future-proofing</td></tr><tr><th>Intel generation</th><td>11th-gen (2021)</td><td class="hi">12th-gen (2022) &mdash; one gen ahead</td></tr><tr><th>Screen &amp; build</th><td>14-inch Full HD business-class Latitude</td><td>14-inch Full HD business-class Latitude</td></tr><tr><th>Price from (refurbished, incl. new 1TB Samsung 990 PRO + setup)</th><td>&pound;540</td><td>&pound;555</td></tr><tr><th>With every 365 machine</th><td>New Samsung Pro SSD &middot; clean licensed Windows &middot; 5-year guarantee</td><td>New Samsung Pro SSD &middot; clean licensed Windows &middot; 5-year guarantee</td></tr><tr><th>Bottom line</th><td class="hi">Smarter-value pick for most refurbished buyers</td><td>Worth the small premium for heavy use or a longer horizon</td></tr></tbody></table></div>'''),
  'dell-latitude-series-explained-3000-5000-7000': ('Dell Latitude 3000 vs 5000 vs 7000 at a glance', '''<div class="cmp-wrap"><table class="cmp-table cmp-table--vs"><thead><tr><th>&nbsp;</th><th>Latitude 3000</th><th>Latitude 5000</th><th>Latitude 7000</th></tr></thead><tbody><tr><th>Best for</th><td>Light everyday use &mdash; browsing, email &amp; Office; a student or a spare</td><td class="hi">All-round daily work for most people</td><td>Carrying everywhere &mdash; maximum portability</td></tr><tr><th>Build &amp; materials</th><td>Entry tier &mdash; more plastic in the chassis</td><td>Sturdier &mdash; metal lid on many models</td><td>Aluminium or carbon fibre, thin &amp; light</td></tr><tr><th>Price from (365, refurbished)</th><td>A little below a 5000</td><td class="hi">From &pound;510</td><td>More than a 5000 &mdash; sourced to order</td></tr><tr><th>Stock with 365</th><td>Sourced to order</td><td class="hi">Our most-stocked tier</td><td>Sourced to order</td></tr><tr><th>Bottom line</th><td>Budget-friendly if money is tight</td><td class="hi">Best all-round value &mdash; our pick for most</td><td>Premium feel, but you pay more</td></tr></tbody></table></div>'''),
  'dell-optiplex-micro-sff-tower-which-to-buy': ('Dell OptiPlex Micro vs SFF vs Tower at a glance', '''<div class="cmp-wrap"><table class="cmp-table cmp-table--vs"><thead><tr><th>&nbsp;</th><th>Micro</th><th>SFF</th><th>Tower</th></tr></thead><tbody><tr><th>Best for</th><td>Reception desks, hot-desks, kiosks &amp; tight or quiet spaces</td><td class="hi">Everyday office work &mdash; the default pick for most desks</td><td>CAD, 3D, video editing &amp; multi-screen design</td></tr><tr><th>Size &amp; noise</th><td class="hi">Tiny (about 1 litre), VESA-mounts behind a monitor, near-silent</td><td>Slim desktop, quiet, internal power supply</td><td>Largest body, most room inside</td></tr><tr><th>Graphics card</th><td>None &mdash; no add-in slots</td><td>Low-profile (half-height) card only</td><td class="hi">Full-size dedicated card &#10003;</td></tr><tr><th>RAM &amp; SSD upgrades</th><td>Laptop memory + a fast M.2 SSD</td><td>Desktop RAM + M.2 &amp; a 2.5-inch or 3.5-inch drive</td><td>Most memory &amp; the most drive bays</td></tr><tr><th>Price from (refurbished)</th><td>From &pound;510</td><td>From &pound;510</td><td>From &pound;510</td></tr><tr><th>Bottom line</th><td>Buy if space &amp; silence beat expansion</td><td class="hi">Buy this unless you have a reason not to</td><td>Buy only if you need a full-size graphics card</td></tr></tbody></table></div>'''),
  'dell-optiplex-vs-inspiron-desktop': ('Dell OptiPlex vs Inspiron desktop at a glance', '''<div class="cmp-wrap"><table class="cmp-table cmp-table--vs"><thead><tr><th>&nbsp;</th><th>Dell OptiPlex</th><th>Dell Inspiron</th></tr></thead><tbody><tr><th>Best for</th><td>Keeping, upgrading &amp; relying on for years &mdash; better long-term value</td><td>Light home use &mdash; browsing, email, video calls &amp; word processing</td></tr><tr><th>Dell line &amp; build</th><td class="hi">Business-grade commercial line &mdash; tougher, minimal bloatware</td><td>Consumer value line &mdash; budget-first, more bundled trialware</td></tr><tr><th>Upgradeable</th><td class="hi">SFF &amp; tower open tool-less; standard parts for easy SSD &amp; memory upgrades</td><td>Usually less room; can use compact or proprietary parts</td></tr><tr><th>Windows edition</th><td class="hi">Typically Windows Pro</td><td>Usually Windows Home</td></tr><tr><th>Price from (365 Techies)</th><td class="hi">Refurbished from &pound;510</td><td>New, budget-first pricing</td></tr><tr><th>Bottom line</th><td class="hi">&#10003; What we steer most home &amp; small-business buyers to &mdash; a refurbished OptiPlex</td><td>Fine if you only need the basics at the lowest up-front cost</td></tr></tbody></table></div>'''),
  'dell-precision-vs-latitude': ('Dell Latitude vs Precision at a glance', '''<div class="cmp-wrap"><table class="cmp-table cmp-table--vs"><thead><tr><th>&nbsp;</th><th>Dell Latitude</th><th>Dell Precision</th></tr></thead><tbody><tr><th>Best for</th><td>Office work, email, browsing, accounts &amp; everyday business</td><td>CAD, 3D, rendering, 4K video &amp; simulation</td></tr><tr><th>What it is</th><td>Dell&rsquo;s mainstream business laptop</td><td>Dell&rsquo;s mobile workstation</td></tr><tr><th>Graphics &amp; memory</th><td>Plenty for everyday apps</td><td>Workstation-class graphics &amp; more memory</td></tr><tr><th>ISV certification</th><td>Not certified</td><td class="hi">&#10003; Tested &amp; approved for pro software</td></tr><tr><th>Refurbished from</th><td>&pound;510</td><td>&pound;510</td></tr><tr><th>Bottom line</th><td class="hi">Right for almost everyone &mdash; and cheaper</td><td>Only if you run heavy pro software daily</td></tr></tbody></table></div>'''),
  'windows-10-esu-or-upgrade-your-dell': ('Windows 10 ESU vs a free Windows 11 upgrade vs a refurbished Dell', '''<div class="cmp-wrap"><table class="cmp-table cmp-table--vs"><thead><tr><th>&nbsp;</th><th>Free Windows 11 upgrade</th><th>Windows 10 ESU</th><th>Refurbished Dell</th></tr></thead><tbody><tr><th>Best for</th><td>A Dell that passes the check &mdash; roughly 2018 onward</td><td>A good, quick Dell that just fails the Windows 11 check</td><td>A tired, slow or pre-2018 Dell not worth propping up</td></tr><tr><th>Cost from</th><td class="hi">Free</td><td>Free with Windows Backup, 1,000 Rewards points, or a small one-off fee</td><td>From &pound;510</td></tr><tr><th>What you get</th><td class="hi">Full Windows 11 &mdash; supported for years</td><td>Security patches only &mdash; no new features, fixes or support</td><td>Newer Dell with a new SSD &amp; licensed Windows 11</td></tr><tr><th>How long it lasts</th><td>Years &mdash; a proper long-term fix</td><td>Runs to October 2027, then stops</td><td class="hi">Years, plus a 365 Techies 5-year guarantee (with a support plan)</td></tr><tr><th>Bottom line</th><td class="hi">Best if it passes &mdash; skip ESU, upgrade free</td><td>A cheap bridge while you plan your upgrade</td><td>Best value for a tired or ageing Dell</td></tr></tbody></table></div>'''),
  'dell-business-support-dorset': ('In-house DIY vs 365 Techies Dell support at a glance', '''<div class="cmp-wrap"><table class="cmp-table cmp-table--vs"><thead><tr><th>&nbsp;</th><th>Keep it in-house</th><th>365 Techies plan</th></tr></thead><tbody><tr><th>Best for</th><td>In-house teams with time to keep every Dell patched &amp; backed up themselves</td><td>Dorset SMEs who just want their Latitude &amp; OptiPlex fleet looked after</td></tr><tr><th>Who you phone</th><td>Your own staff, squeezed around the day job</td><td class="hi">One local team you can phone &mdash; same faces every time &mdash; on 01202 775566</td></tr><tr><th>What it covers</th><td>Whatever you find time for</td><td class="hi">Monitoring, patching, health checks, security &amp; backups &mdash; six-weekly</td></tr><tr><th>On-site in Dorset</th><td>In-house only</td><td class="hi">Bournemouth, Poole &amp; Christchurch, or free local collection &mdash; no call-out fee</td></tr><tr><th>When a Dell dies</th><td>Shop around online &mdash; risk a worn battery &amp; mystery Windows install</td><td class="hi">Refurbished business-grade Dell from &pound;510 &mdash; new SSD, clean licensed Windows, 5-year guarantee</td></tr><tr><th>Price from</th><td>Staff time &mdash; hard to pin down</td><td class="hi">&pound;24.38 per computer a month from an independent Dell specialist &mdash; no VAT, no tie-in</td></tr></tbody></table></div>'''),
}


